 reponse:[["['ville manque']","Pour {\"nom\": \"Awa\", \"montant\": 12500} : un champ obligatoire manque"],["[\"montant n'est pas un int\"]","Pour \"montant\": \"12 500\" : du texte à la place d'un nombre"],["True False True","isinstance(12500, int), isinstance(\"12500\", int), isinstance(True, int)"]],
 pieges:[["isinstance(True, int) vaut True","En Python, True compte comme un entier. Pour refuser un vrai ou faux, teste d'abord isinstance(x, bool)."],["NameError: name 'string' is not defined","Le type du texte s'écrit str, pas string."]],
 mots:["string","integer","boolean"],
