 quand:"Autour de chaque json.loads appliqué à un texte écrit par un modèle.",
 lignes:[["try:","essaie de lire"],["    fiche = json.loads(texte)","le texte du modèle"],["except json.JSONDecodeError as e:","ce n'était pas du JSON valable"],["    print(\"Pas du JSON :\", e)","note le problème, puis redemande ou passe au suivant"]],
 reponse:[["Pas du JSON : Expecting value: line 1 column 1 (char 0)","Pour le texte Voici la fiche : {\"nom\": \"Awa\"} : une phrase avant le JSON"]],
 pieges:[["json.decoder.JSONDecodeError: Expecting value: line 1 column 1 (char 0)","Le texte ne commence pas par du JSON : il est vide, ou commence par une phrase, ou par ```json. Affiche-le pour voir."],["json.decoder.JSONDecodeError: Expecting property name enclosed in double quotes: line 1 column 2 (char 1)","Des guillemets simples : {'a': 1} est de l'écriture Python, pas du JSON. Le JSON veut des guillemets doubles."],["except ValueError:","Ça marche aussi : JSONDecodeError est une sorte de ValueError. Nommer l'erreur exacte rend ton code plus clair."]],
